def stretches(x,name):
    res=[]
    for f in range(3):
        cds=[]
        pos=[]
        for i in range(f,n-2,3):
            cds.append(x[i:i+3]); pos.append(i)
        st=0
        for j in range(len(cds)+1):
            if j==len(cds) or cds[j] in stop:
                if j>st:
                    length=(j-st)*3
                    if length>=250:
                        beg=pos[st]; end=pos[j-1]+3
                        res.append((name,f,beg,end,length))
                st=j+1
    return res
